// Auth Validation (hardcoded — N8N_BLOCK_ENV_ACCESS_IN_NODE prevents $env)
const headers = $input.first().json.headers || {};
const body = $input.first().json.body || {};
const secret = headers['x-webhook-secret'] || headers['X-Webhook-Secret'] || '';
const EXPECTED = 'medconnect-n8n-secret-key';
if (secret !== EXPECTED) {
  return [{ json: { success: false, statusCode: 401, error: 'UNAUTHORIZED_WEBHOOK_SECRET', source: 'n8n' } }];
}
return [{ json: { ...body, _n8nAuthenticated: true, _n8nReceivedAt: new Date().toISOString() } }];

// NLP Intent Engine — rule-based, runs entirely in n8n
const data = $input.first().json;
if (data.statusCode === 401) return [{ json: data }];
const text = (data.text || '').toLowerCase();
const lang = data.language || 'Hinglish';
let intent = 'UNKNOWN', confidence = 0.72;
if (/book|appointment|schedule|milna|chahiye/.test(text)) { intent = 'BOOK_APPOINTMENT'; confidence = 0.95; }
else if (/cancel|hatao/.test(text)) { intent = 'CANCEL_APPOINTMENT'; confidence = 0.92; }
else if (/queue|token|wait|status/.test(text)) { intent = 'CHECK_QUEUE'; confidence = 0.91; }
else if (/doctor|available|availability|kab/.test(text)) { intent = 'CHECK_DOCTOR_AVAILABILITY'; confidence = 0.88; }
else if (/emergency|icu|bed|blood|oxygen/.test(text)) { intent = 'EMERGENCY_RESOURCE_REQUEST'; confidence = 0.97; }
const doctorMatch = text.match(/dr\.?\s+([a-z]+(?:\s+[a-z]+)?)/i);
const deptMap = { cardiology: 'Cardiology', ortho: 'Orthopedics', neuro: 'Neurology', general: 'General Medicine' };
let department = '';
for (const [k,v] of Object.entries(deptMap)) { if (text.includes(k)) { department = v; break; } }
const slots = {
  doctorName: doctorMatch ? doctorMatch[1].trim() : null,
  department: department || null,
  date: /today/.test(text) ? new Date().toISOString().split('T')[0] : /tomorrow/.test(text) ? new Date(Date.now()+86400000).toISOString().split('T')[0] : null
};
return [{ json: { ...data, _n8nIntent: intent, _n8nConfidence: confidence, _n8nSlots: slots, _n8nNLPAt: new Date().toISOString(), source: 'n8n' } }];

// DB Validation & Action — simulates Supabase interaction inside n8n
const d = $input.first().json;
if (d.statusCode === 401) return [{ json: d }];
const intent = d._n8nIntent || 'UNKNOWN';
const slots = d._n8nSlots || {};
const lang = d.language || 'Hinglish';
const hospitalId = d.hospitalId || 'hosp-101';
let status = 'INFORMATIONAL', aiMessage = '', actionPayload = null, missingSlots = [];
if (intent === 'BOOK_APPOINTMENT') {
  if (!slots.doctorName && !slots.department) {
    missingSlots = ['doctorName', 'department'];
    aiMessage = lang === 'Hindi' ? 'मुझे डॉक्टर का नाम चाहिए।' : 'Aap kaun se doctor mein appointment chahiye?';
    status = 'NEEDS_MORE_INFO';
  } else {
    const tokenNum = 'MED-' + (Math.floor(Math.random()*900)+100);
    actionPayload = { token: { token_number: tokenNum, status: 'CONFIRMED', doctor: slots.doctorName || 'Auto-assigned', department: slots.department || 'General Medicine', date: slots.date || new Date().toISOString().split('T')[0] } };
    aiMessage = 'Appointment confirmed! Token: ' + tokenNum + '. Please arrive 10 minutes early.';
    status = 'ACTION_COMPLETED';
  }
} else if (intent === 'CHECK_QUEUE') {
  aiMessage = 'Aapka token queue mein hai. Estimated wait: 15-20 minutes.';
  status = 'ACTION_COMPLETED';
} else if (intent === 'CANCEL_APPOINTMENT') {
  aiMessage = 'Appointment cancelled successfully.';
  status = 'ACTION_COMPLETED';
} else if (intent === 'CHECK_DOCTOR_AVAILABILITY') {
  aiMessage = 'Available: Dr. Rajesh Sharma (Cardiology 9AM-2PM), Dr. Priya Ananth (Ortho 10AM-4PM).';
  status = 'ACTION_COMPLETED';
} else if (intent === 'EMERGENCY_RESOURCE_REQUEST') {
  aiMessage = 'Emergency request registered. Nearby hospitals alerted.';
  status = 'ACTION_COMPLETED';
} else {
  aiMessage = lang === 'Hindi' ? 'मैं आपकी कैसे मदद कर सकता हूँ?' : 'Namaskar! Main aapki kya madad kar sakta hoon?';
}
return [{ json: {
  success: true,
  source: 'n8n',
  executedBy: 'local-n8n',
  workflowId: 'wf-ai-receptionist-v14',
  intent,
  confidence: d._n8nConfidence,
  status,
  aiMessage,
  actionPayload,
  missingSlots,
  validatedSlots: slots,
  transcript: d.text || '',
  language: lang,
  hospitalId,
  context: d.context || {},
  _n8nDBAt: new Date().toISOString(),
  configurationStatus: { openaiConfigured: false, sarvamConfigured: false, n8nConfigured: true }
} }];
